export const html = "<header class=\"chrome\">\n  <button class=\"icon-btn glass\" aria-label=\"Close case study\"><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"><path d=\"M4 4l8 8M12 4l-8 8\"/></svg></button>\n  <div class=\"right\">\n    <button class=\"icon-btn glass\" id=\"themeBtn\" aria-label=\"Switch theme\"><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"8\" cy=\"8\" r=\"5.5\"/><path d=\"M8 2.5v11A5.5 5.5 0 0 0 8 2.5z\" fill=\"currentColor\"/></svg></button>\n    <a class=\"pill-btn glass\" href=\"#next\"><span class=\"muted\">Next</span><span class=\"dot\" style=\"background:#ea580c\"></span>Cheffy</a>\n  </div>\n</header>\n\n<main class=\"wrap\">\n  <section class=\"hero-bleed\" id=\"cover\">\n    <!-- Hero motion: /ProjectSidewalk/project-sidewalk-thumbnail-v3.mp4 (poster: Explore screen) -->\n    <div class=\"hero-art sw-art\" aria-hidden=\"true\"></div>\n    <video class=\"hero-video\" id=\"heroVideo\" autoplay muted loop playsinline preload=\"auto\" poster=\"/ProjectSidewalk/PS_FinalPRoduct.png\" data-site=\"/ProjectSidewalk/project-sidewalk-thumbnail-v3.mp4\" aria-hidden=\"true\"><source src=\"\" type=\"video/mp4\"></video>\n    <div class=\"hero-inner\">\n      <div class=\"hero-top\"><span class=\"tag on-img\">Project Sidewalk</span><span class=\"t-small\">Crowdsourced accessibility map</span></div>\n          <div class=\"hero-grid\">\n            <div class=\"hero-left\">\n            <h1 class=\"t-display\">Making accessibility<br>automatic</h1>\n            <button class=\"btn-summary\" data-open-summary><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><rect x=\"2\" y=\"2\" width=\"5\" height=\"5\" rx=\"1\"/><rect x=\"9\" y=\"2\" width=\"5\" height=\"5\" rx=\"1\"/><rect x=\"2\" y=\"9\" width=\"5\" height=\"5\" rx=\"1\"/><rect x=\"9\" y=\"9\" width=\"5\" height=\"5\" rx=\"1\"/></svg>Read the 2-min summary <span class=\"sub\">5 slides</span></button>\n          </div>\n          <div class=\"hero-right\">\n          <p class=\"t-lead\"><b>I built Project Sidewalk's first design system with WCAG 2.2 AA baked in.</b> Contrast pass rate went from 37% to 100%, and 3 teams adopted it with zero added accessibility effort.</p>\n          <div class=\"tags\"><span class=\"tag on-img\">Design System</span><span class=\"tag on-img\">Accessibility</span><span class=\"tag on-img\">Civic Tech</span></div>\n          \n          <a class=\"store-link\" href=\"https://sidewalk-chicago.cs.washington.edu/\" target=\"_blank\" rel=\"noopener\">Visit the live project ↗</a>\n        </div>\n      </div>\n    </div>\n  </section>\n  <section class=\"hero\">\n    <div class=\"meta\">\n      <div><div class=\"t-caption\">Role</div><div class=\"t-label\">Lead Product Designer</div></div>\n      <div><div class=\"t-caption\">Timeline</div><div class=\"t-label\">12 months</div></div>\n      <div><div class=\"t-caption\">Team</div><div class=\"t-label\">PM · 2 developers</div></div>\n      <div><div class=\"t-caption\">Domain</div><div class=\"t-label\">Civic tech · open source</div></div>\n    </div>\n\n    <div class=\"glance-head\"><span class=\"t-caption\">At a glance</span></div>\n    <div class=\"tldr\">\n      <div><div class=\"t-caption\">Problem</div><p class=\"t-small\"><b>An accessibility tool that failed accessibility.</b> 37% of components passed contrast, with 4 different button styles and no shared system.</p></div>\n      <div><div class=\"t-caption\">Approach</div><p class=\"t-small\"><b>Audit, then architecture.</b> Hotjar, community issues and a WCAG audit led to tokens and a component library that is accessible by default.</p></div>\n      <div><div class=\"t-caption\">Outcome</div><p class=\"t-small\"><b>0 axe-core violations.</b> Contrast 37% → 100% across 24 components, adopted by 3 teams serving 11,000+ volunteers.</p></div>\n    </div>\n\n    <div class=\"role reveal\">\n      <div class=\"role-head\"><span class=\"t-caption\">What I did</span><span class=\"t-caption\">Click to jump</span></div>\n      <div class=\"role-grid\">\n        <a href=\"#research\"><span class=\"t-label\">Data-informed diagnostics</span><span class=\"t-caption\">Hotjar · community voice · WCAG audit</span></a>\n        <a href=\"#system\"><span class=\"t-label\">Architected an accessible-by-default system</span><span class=\"t-caption\">Token foundation → component library</span></a>\n        <a href=\"#adoption\"><span class=\"t-label\">Scaled cross-functional adoption</span><span class=\"t-caption\">1 PM · 2 developers · phased rollout</span></a>\n        <a href=\"#outcome\"><span class=\"t-label\">Delivered measurable impact</span><span class=\"t-caption\">11k+ users · 0 axe-core violations</span></a>\n      </div>\n      <div class=\"team\"><span class=\"t-caption\">Team</span><span class=\"tag accent\">Me · system architecture lead</span><span class=\"tag\">PM</span><span class=\"tag\">2 developers</span></div>\n    </div>\n  </section>\n\n  <div class=\"case\">\n    <aside class=\"toc\" id=\"toc\" aria-label=\"Sections\">\n      <ol>\n        <li><a href=\"#context\"><span>01</span>Context</a></li>\n        <li><a href=\"#people\"><span>02</span>Stakeholders</a></li>\n        <li><a href=\"#research\"><span>03</span>Research</a></li>\n        <li><a href=\"#system\"><span>04</span>System</a></li>\n        <li><a href=\"#adoption\"><span>05</span>Adoption</a></li>\n        <li><a href=\"#outcome\"><span>06</span>Outcome</a></li>\n        <li><a href=\"#reflection\"><span>07</span>Reflection</a></li>\n      </ol>\n    </aside>\n\n    <div>\n      <!-- 01 -->\n      <section class=\"sec\" id=\"context\">\n        <div class=\"eyebrow\"><span class=\"n\">01</span>Context</div>\n        <h2 class=\"t-h2\">Growing pains and accessibility debt</h2>\n        <p class=\"t-body\">Project Sidewalk is an open-source civic platform that crowdsources urban accessibility data to train machine learning models. With <b>350,000+ accessibility labels</b> from <b>11,000+ volunteers</b>, it had proven its value. Underneath, the architecture and experience were brittle.</p>\n\n        <div class=\"list reveal\">\n          <div><span class=\"n\">01</span><div><div class=\"t-h3\">User drop-off</div><p class=\"t-small\">Inconsistent UI and unclear feedback caused high abandonment in the core reporting flows.</p></div></div>\n          <div><span class=\"n\">02</span><div><div class=\"t-h3\">Engineering bottleneck</div><p class=\"t-small\">With no central design system, developers rebuilt components from scratch, piling up technical debt and frontend regressions.</p></div></div>\n          <div><span class=\"n\">03</span><div><div class=\"t-h3\">The accessibility irony</div><p class=\"t-small\">A tool built for accessibility failed basic WCAG standards, alienating the very community it served.</p></div></div>\n        </div>\n\n        <figure class=\"breakout panel audit reveal\" aria-label=\"WCAG 2.2 AA initial audit\">\n          <div class=\"chart-head\">\n            <div><div class=\"t-label\">WCAG 2.2 AA audit, before</div><div class=\"t-caption\">Initial assessment across core pages · illustrative</div></div>\n            <div class=\"chart-call\"><span class=\"t-label\" style=\"color:var(--accent)\">Screen reader</span><span class=\"t-caption\">the weakest area</span></div>\n          </div>\n          <div class=\"hbars\">\n            <div class=\"hb\"><span class=\"l\">Color contrast</span><span class=\"tr\"><i style=\"--w:37%\"></i></span><span class=\"v\">37%</span></div>\n            <div class=\"hb\"><span class=\"l\">Keyboard navigation</span><span class=\"tr\"><i style=\"--w:42%\"></i></span><span class=\"v\">42%</span></div>\n            <div class=\"hb hot\"><span class=\"l\">Screen reader</span><span class=\"tr\"><i style=\"--w:28%\"></i></span><span class=\"v\">28%</span></div>\n            <div class=\"hb\"><span class=\"l\">Focus indicators</span><span class=\"tr\"><i style=\"--w:51%\"></i></span><span class=\"v\">51%</span></div>\n          </div>\n          <figcaption class=\"t-caption\">Pass rate. Values are illustrative. Actual audit data is confidential.</figcaption>\n        </figure>\n      </section>\n\n      <!-- 02 -->\n      <section class=\"sec\" id=\"people\">\n        <div class=\"eyebrow\"><span class=\"n\">02</span>Stakeholders</div>\n        <h2 class=\"t-h2\">Three groups, one answer</h2>\n        <p class=\"t-body\">Redesigning a civic platform meant balancing three groups with competing needs. An accessible-by-default design system was the only way to serve all of them at once.</p>\n        <div class=\"groups reveal\">\n          <div class=\"tile\"><span class=\"t-caption\">The mappers</span><div class=\"t-h3\">Citizens &amp; volunteers</div><ul><li>Map barriers quickly and accurately</li><li>Low cognitive load, gamified flows</li><li>WCAG AA compliant interface</li></ul></div>\n          <div class=\"tile\"><span class=\"t-caption\">Data consumers</span><div class=\"t-h3\">City planners &amp; governments</div><ul><li>High data accuracy for planning</li><li>Standardized reporting formats</li><li>Reliable UI that prevents input errors</li></ul></div>\n          <div class=\"tile\"><span class=\"t-caption\">Internal team</span><div class=\"t-h3\">Engineers &amp; maintainers</div><ul><li>Scale to 8+ cities without regressions</li><li>A reusable component library</li><li>Fewer UI-related GitHub issues</li></ul></div>\n        </div>\n      </section>\n\n      <!-- 03 -->\n      <section class=\"sec\" id=\"research\">\n        <div class=\"eyebrow\"><span class=\"n\">03</span>Research</div>\n        <h2 class=\"t-h2\">Data-informed diagnostics</h2>\n        <p class=\"t-body\">Instead of relying on intuition, I audited the existing experience with quantitative and qualitative data to find the highest-impact fixes.</p>\n        <div class=\"methods reveal\">\n          <div><span class=\"t-caption\">Behavioral analysis</span><p class=\"t-small\">Hotjar heatmaps and session recordings to find drop-off points, navigation friction and hesitation.</p></div>\n          <div><span class=\"t-caption\">Community voice</span><p class=\"t-small\">GitHub issues and forum discussions, synthesized into prioritized pain points.</p></div>\n          <div><span class=\"t-caption\">WCAG 2.2 AA audit</span><p class=\"t-small\">A heuristic evaluation for contrast, keyboard navigation and screen reader support.</p></div>\n        </div>\n\n        <figure class=\"breakout panel heat reveal\" aria-label=\"Heatmap findings on the labeling page\">\n          <div class=\"heat-grid\">\n            <div class=\"browser\">\n              <div class=\"bar\"><i></i><i></i><i></i><span>sidewalks.umd.edu/label</span></div>\n              <div class=\"page\">\n                <div class=\"side\"><span></span><span></span><span></span><span></span><div class=\"hz z2\"></div></div>\n                <div class=\"mapv\"><div class=\"hz z1\"></div><div class=\"hz z3\"></div>\n                  <button class=\"mk\" data-f=\"0\" style=\"left:50%;top:45%\">1</button>\n                  <button class=\"mk\" data-f=\"1\" style=\"left:-4%;top:28%\">2</button>\n                  <button class=\"mk\" data-f=\"2\" style=\"left:50%;top:86%\">3</button>\n                  <div class=\"valbtns\"><span></span><span></span><span></span></div>\n                </div>\n              </div>\n            </div>\n            <div class=\"finds\">\n              <div class=\"find on\" data-f=\"0\"><span class=\"t-caption\">1 · 68% of clicks</span><div class=\"t-h3\">Map center</div><p class=\"t-small\">Users concentrated on the center and struggled to find labels outside the current viewport.</p></div>\n              <div class=\"find\" data-f=\"1\"><span class=\"t-caption\">2 · 42% drop-off</span><div class=\"t-h3\">Sidebar controls</div><p class=\"t-small\">Users abandoned sidebar label controls after the first try. Navigation was unclear.</p></div>\n              <div class=\"find\" data-f=\"2\"><span class=\"t-caption\">3 · Highest engagement</span><div class=\"t-h3\">Validation buttons</div><p class=\"t-small\">The strongest click-through. Users understood the core labeling task.</p></div>\n            </div>\n          </div>\n        </figure>\n        <p class=\"t-caption fig-cap\">Recreated visualization. Hotjar data is confidential; patterns and proportions reflect real findings.</p>\n      </section>\n\n      <!-- 04 -->\n      <section class=\"sec\" id=\"system\">\n        <div class=\"eyebrow\"><span class=\"n\">04</span>System</div>\n        <h2 class=\"t-h2\">Accessible by default</h2>\n        <p class=\"t-body\">My goal shifted from delivering polished screens to building infrastructure. Two decisions made compliance automatic instead of something to fix later.</p>\n\n        <div class=\"decisions\">\n          <div class=\"dec reveal\">\n            <div class=\"dec-text\"><span class=\"t-caption\">Decision 01</span><div class=\"t-h3\">Tokens as a single source of truth</div><p class=\"t-small\">I defined atomic design tokens and mapped Figma variables 1:1 to the engineers' SCSS variables, removing guesswork at handoff.</p></div>\n            <div class=\"dec-vis tile\"><div class=\"tokmap\">\n              <div class=\"tk-col\"><span class=\"t-caption\">Figma tokens</span><code>color.primary</code><code>color.text</code><code>spacing.md</code></div>\n              <div class=\"tk-mid\" aria-hidden=\"true\"><span>↔</span><span>↔</span><span>↔</span></div>\n              <div class=\"tk-col\"><span class=\"t-caption\">SCSS variables</span><code>$color-primary</code><code>$color-text</code><code>$spacing-md: 16px</code></div>\n            </div></div>\n          </div>\n          <div class=\"dec reveal\">\n            <div class=\"dec-text\"><span class=\"t-caption\">Decision 02</span><div class=\"t-h3\">Compliance built into components</div><p class=\"t-small\">Every component ships WCAG 2.2 AA compliant. Any future feature built from them inherits accessibility, with no retroactive fixes.</p></div>\n            <div class=\"dec-vis tile\"><div class=\"inherit\">\n              <span class=\"ih base\">Component library · WCAG 2.2 AA</span>\n              <span class=\"ih-arr\">↓</span>\n              <div class=\"ih-row\"><span class=\"ih\">New feature</span><span class=\"ih\">New city</span><span class=\"ih\">New team</span></div>\n              <span class=\"t-caption\">Inherits contrast, focus, labels and touch targets</span>\n            </div></div>\n          </div>\n        </div>\n\n        <!-- SIGNATURE: legacy vs system -->\n        <div class=\"breakout panel sys reveal\" id=\"sysDemo\">\n          <div class=\"sys-head\">\n            <div><div class=\"t-label\">Flip the system on</div><div class=\"t-caption\">Same screen, legacy UI vs. the design system</div></div>\n            <div class=\"seg\" role=\"radiogroup\" aria-label=\"UI version\">\n              <button role=\"radio\" aria-checked=\"true\" data-v=\"legacy\">Legacy</button>\n              <button role=\"radio\" aria-checked=\"false\" data-v=\"system\">Design system</button>\n            </div>\n          </div>\n          <div class=\"sys-grid\">\n            <div class=\"ui-prev legacy\" id=\"uiPrev\">\n              <div class=\"up-row\"><span class=\"t-caption-ui\">Validations</span></div>\n              <div class=\"up-row vbtns\">\n                <button class=\"vb v1\"><i class=\"ic ok\"></i><span data-l=\"Correct\" data-s=\"Validate correct\">Correct</span></button>\n                <button class=\"vb v2\"><i class=\"ic no\"></i><span data-l=\"Incorrect\" data-s=\"Validate incorrect\">Incorrect</span></button>\n                <button class=\"vb v3\"><i class=\"ic q\"></i><span data-l=\"Not sure\" data-s=\"Unsure\">Not sure</span></button>\n                <button class=\"vb v4\"><i class=\"ic un\"></i><span data-l=\"skip\" data-s=\"Unvalidated\">skip</span></button>\n              </div>\n              <div class=\"up-row\"><span class=\"t-caption-ui\">Severity range</span></div>\n              <div class=\"up-row sev\"><span class=\"on\">Any</span><span>1</span><span>2</span><span>3</span><span>4</span><span>5</span></div>\n              <div class=\"up-row\"><span class=\"t-caption-ui\">Label type</span></div>\n              <div class=\"up-row chips\">\n                <span class=\"lc c1\"><i class=\"rd on\"></i>Any type</span><span class=\"lc c2\"><i class=\"rd\"></i>Curb Ramp</span><span class=\"lc c3\"><i class=\"rd\"></i>Missing Curb Ramp</span><span class=\"lc c4\"><i class=\"rd\"></i>Obstacle In Path</span>\n              </div>\n              <div class=\"up-row\"><input class=\"srch\" aria-label=\"City\" placeholder=\"Chicago\"></div>\n            </div>\n            <div class=\"sys-audit\">\n              <div class=\"sa-row\"><span class=\"l\">Color contrast</span><span class=\"tr\"><i id=\"aC\"></i></span><span class=\"v\" id=\"vC\"></span></div>\n              <div class=\"sa-row\"><span class=\"l\">Keyboard navigation</span><span class=\"tr\"><i id=\"aK\"></i></span><span class=\"v\" id=\"vK\"></span></div>\n              <div class=\"sa-row\"><span class=\"l\">Screen reader</span><span class=\"tr\"><i id=\"aS\"></i></span><span class=\"v\" id=\"vS\"></span></div>\n              <div class=\"sa-row\"><span class=\"l\">Focus indicators</span><span class=\"tr\"><i id=\"aF\"></i></span><span class=\"v\" id=\"vF\"></span></div>\n              <div class=\"sa-sum\" id=\"aSum\"></div>\n            </div>\n          </div>\n        </div>\n        <p class=\"t-caption fig-cap\">Legacy values are the illustrative pre-audit. System values match the final axe-core and manual NVDA + VoiceOver checks.</p>\n      </section>\n\n      <section class=\"statement reveal\" aria-label=\"Core design principle\">\n        <p>Treat design as <em>infrastructure</em>, not surface. Build systems that make <em>compliance automatic</em>.</p>\n        <span class=\"t-caption\">Core design principle</span>\n      </section>\n\n      <!-- 05 -->\n      <section class=\"sec\" id=\"adoption\">\n        <div class=\"eyebrow\"><span class=\"n\">05</span>Adoption</div>\n        <h2 class=\"t-h2\">A working contract, not a style guide</h2>\n        <p class=\"t-body\">A design system is only as good as its adoption. Working closely with 1 PM and 2 developers, I treated it as a working contract between design and engineering, rolled it out in phases with detailed spec handoffs, and championed it across the organization.</p>\n\n        <figure class=\"breakout panel duo reveal\" aria-label=\"Validation buttons and label colors before and after\">\n          <div class=\"duo-col\">\n            <div class=\"duo-label\"><span class=\"tag\">Before</span><span class=\"t-caption\">Fragmented</span></div>\n            <div class=\"sw-ui dim\">\n              <div class=\"vbtns legacy\"><button class=\"vb v1\">Correct</button><button class=\"vb v2\">Incorrect</button><button class=\"vb v3\">Not sure</button><button class=\"vb v4\">skip</button></div>\n              <ul class=\"sw-notes\"><li>Mixed shapes, sizes and naming</li><li>No semantic token mapping</li><li>Label colors varied per page</li></ul>\n            </div>\n          </div>\n          <div class=\"duo-col\">\n            <div class=\"duo-label\"><span class=\"tag accent\">After</span><span class=\"t-caption\">Systematic</span></div>\n            <div class=\"sw-ui\">\n              <div class=\"vbtns system\"><button class=\"vb\"><i class=\"ic ok\"></i>Validate correct</button><button class=\"vb\"><i class=\"ic no\"></i>Validate incorrect</button><button class=\"vb\"><i class=\"ic q\"></i>Unsure</button><button class=\"vb\"><i class=\"ic un\"></i>Unvalidated</button></div>\n              <div class=\"toks\"><span style=\"--c:#4b5563\">asphalt</span><span style=\"--c:#15803d\">pine</span><span style=\"--c:#ca8a04\">banana</span><span style=\"--c:#ea580c\">orange</span></div>\n              <ul class=\"sw-notes on\"><li>One chip pattern: icon + label, same size and spacing</li><li>9 semantic label tokens + 4 brand primitives</li></ul>\n            </div>\n          </div>\n        </figure>\n        <p class=\"t-caption fig-cap\">Validation chips before and after the system.</p>\n        <figure class=\"breakout panel shot reveal\" aria-label=\"Project Sidewalk component library\">\n          <img src=\"/ProjectSidewalk/PS_designsystem_overview.webp\" alt=\"The Project Sidewalk component library: accessible-by-default components with WCAG 2.2 AA baked in\" loading=\"lazy\" width=\"1400\" height=\"1212\" style=\"width:100%;display:block;border-radius:10px 10px 0 0\">\n        </figure>\n      </section>\n\n      <!-- 06 -->\n      <section class=\"sec\" id=\"outcome\">\n        <div class=\"eyebrow\"><span class=\"n\">06</span>Outcome</div>\n        <h2 class=\"t-h2\">Accessibility became the default</h2>\n        <p class=\"t-body\">What began as a UI cleanup became a strategy for scaling a civic tool through resilient design.</p>\n        <div class=\"deltas reveal\">\n          <div><div class=\"t-caption\">Contrast pass rate</div><div class=\"delta\"><s>37%</s><span class=\"arr\">→</span><b>100%</b></div><div class=\"t-small\">axe-core, 24 components</div></div>\n          <div><div class=\"t-caption\">axe-core violations</div><div class=\"delta\"><b>0</b></div><div class=\"t-small\">Verified manually with NVDA + VoiceOver</div></div>\n        </div>\n        <div class=\"stats-xl reveal\">\n          <div><span class=\"num\">24</span><span class=\"t-small\">components · 9 semantic tokens</span></div>\n          <div><span class=\"num accent\">3</span><span class=\"t-small\">teams adopted it with zero added a11y effort</span></div>\n          <div><span class=\"num\">11k+</span><span class=\"t-small\">volunteers on an accessible platform</span></div>\n        </div>\n        <p class=\"t-small\" style=\"margin-top:24px;max-width:640px\">Adoption across 3 cross-functional teams cut engineering overhead, sped up feature delivery and sharply reduced UI-related frontend bugs.</p>\n\n        <figure class=\"breakout term reveal\" aria-label=\"axe-core audit output\">\n          <div class=\"term-bar\"><i></i><i></i><i></i><span>wcag-audit · WCAG 2.2 AA</span></div>\n          <pre><span class=\"pr\">$</span> npx axe-core --standard wcag2aa ./components\n<span class=\"mu\">Running accessibility audit on 24 components…</span>\n\n<span class=\"ok\">✓</span> Color contrast      <span class=\"ok\">0 violations · 4.5:1+ all text</span>\n<span class=\"ok\">✓</span> Keyboard flow       <span class=\"ok\">24/24 components reachable</span>\n<span class=\"ok\">✓</span> Screen reader       <span class=\"ok\">NVDA + VoiceOver verified</span>\n<span class=\"ok\">✓</span> Focus indicators    <span class=\"ok\">Visible on all interactive elements</span>\n<span class=\"ok\">✓</span> ARIA labels         <span class=\"ok\">All roles and landmarks defined</span>\n<span class=\"ok\">✓</span> Touch targets       <span class=\"ok\">44px minimum · spacing compliant</span>\n\n<span class=\"ok\">6 checks passed</span> <span class=\"mu\">· 0 failed · 0 warnings</span>\n<span class=\"mu\">Completed in 2.4s · Standard: WCAG 2.2 AA · Tool: axe-core 4.8</span></pre>\n        </figure>\n        <figure class=\"breakout panel shot reveal\" aria-label=\"Explore page built with the design system\">\n          <img class=\"ps-shot\" src=\"/ProjectSidewalk/PS_FinalPRoduct.png\" alt=\"Project Sidewalk Explore page: filters, label results and map\" loading=\"lazy\" width=\"3456\" height=\"2234\">\n        </figure>\n        <p class=\"t-caption fig-cap\">Explore, built entirely from system components: filters, validation chips, label cards</p>\n      </section>\n\n      <!-- 07 -->\n      <section class=\"sec\" id=\"reflection\" style=\"border-bottom:0\">\n        <div class=\"eyebrow\"><span class=\"n\">07</span>Reflection</div>\n        <h2 class=\"t-h2\">Systems thinking in civic tech</h2>\n        <div class=\"insight reveal\" style=\"margin-top:8px\"><p>A design system isn't just a style guide. <em>It lets inclusivity live in the code, not only the pixels.</em></p></div>\n        <div class=\"list reveal\">\n          <div><span class=\"n\">01</span><div><div class=\"t-h3\">Designing for resilience</div><p class=\"t-small\">The project moved me from designing for the happy path to designing for resilience in open-source, civic environments.</p></div></div>\n          <div><span class=\"n\">02</span><div><div class=\"t-h3\">Infrastructure over surface</div><p class=\"t-small\">Treating design as infrastructure let 3 teams ship accessible features without extra effort.</p></div></div>\n          <div><span class=\"n\">03</span><div><div class=\"t-h3\">Scale needs a system</div><p class=\"t-small\">In civic tech a design system isn't a luxury. When inclusivity is in the architecture, every new feature inherits it.</p></div></div>\n        </div>\n      </section>\n    </div>\n  </div>\n\n  <a class=\"next\" id=\"next\" href=\"#\">\n    <div class=\"row\">\n      <div><div class=\"t-caption\" style=\"margin-bottom:8px\">Next project · Cheffy</div><div class=\"t-h2\">A cooking UI that adapts when your hands are full</div></div>\n      <span class=\"arrow\" aria-hidden=\"true\">→</span>\n    </div>\n    <div class=\"panel nx-cheffy\"><div class=\"nx-chip orange\">Elbow-bump mode · &lt;400ms</div></div>\n  </a>\n</main>\n\n<div class=\"sum\" id=\"sum\" hidden role=\"dialog\" aria-modal=\"true\" aria-label=\"Summary mode\">\n  <div class=\"sum-card\">\n    <div class=\"sum-top\">\n      <div class=\"sum-dots\" id=\"sumDots\"><i class=\"on\"></i><i></i><i></i><i></i><i></i></div>\n      <span class=\"t-caption sum-role\">Project Sidewalk · Lead Product Designer · 12 months</span>\n      <button class=\"icon-btn\" id=\"sumClose\" aria-label=\"Close summary\"><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"><path d=\"M4 4l8 8M12 4l-8 8\"/></svg></button>\n    </div>\n    <div class=\"slide on\">\n      <div class=\"s-l\"><span class=\"t-caption\">01 · Problem</span><p class=\"big\">An accessibility tool that <em>failed accessibility.</em></p><p class=\"t-small\">Project Sidewalk serves 11,000+ volunteers mapping barriers, but its own UI failed WCAG: inconsistent components, low contrast, weak screen reader support.</p></div>\n      <div class=\"s-r\"><div class=\"mini-bars m4\"><div><i style=\"--h:37%\"></i><span>Contrast</span></div><div><i style=\"--h:42%\"></i><span>Keyboard</span></div><div class=\"hot\"><i style=\"--h:28%\"></i><span>Reader</span></div><div><i style=\"--h:51%\"></i><span>Focus</span></div></div><p class=\"t-caption\">Initial WCAG audit pass rates · illustrative</p></div>\n    </div>\n    <div class=\"slide\">\n      <div class=\"s-l\"><span class=\"t-caption\">02 · Insight</span><p class=\"big\">Three groups needed <em>one answer.</em></p><p class=\"t-small\">Volunteers, city planners and engineers had competing needs. Hotjar, community issues and a WCAG audit showed an accessible-by-default system could serve all three.</p></div>\n      <div class=\"s-r s-rows\"><div><span class=\"t-caption\">Mappers</span><p class=\"t-label\">Fast, low-load, AA-compliant flows</p></div><div><span class=\"t-caption\">City planners</span><p class=\"t-label\">Accurate, standardized data</p></div><div><span class=\"t-caption\">Engineers</span><p class=\"t-label\">Reusable components, fewer regressions</p></div></div>\n    </div>\n    <div class=\"slide\">\n      <div class=\"s-l\"><span class=\"t-caption\">03 · System</span><p class=\"big\">Compliance <em>built into every component.</em></p><p class=\"t-small\">Atomic tokens mapped 1:1 from Figma to SCSS, and a component library that ships WCAG 2.2 AA by default.</p></div>\n      <div class=\"s-r s-rows\"><div><span class=\"t-caption\">Foundation</span><p class=\"t-label\">9 semantic tokens + 4 brand primitives</p></div><div><span class=\"t-caption\">Library</span><p class=\"t-label\">24 components, accessible by default</p></div></div>\n    </div>\n    <div class=\"slide\">\n      <div class=\"s-l\"><span class=\"t-caption\">04 · Adoption</span><p class=\"big\">A working contract, <em>not a style guide.</em></p><p class=\"t-small\">Phased rollout and detailed handoffs with 1 PM and 2 developers. Design as infrastructure, not surface.</p></div>\n      <div class=\"s-r s-rows\"><div><span class=\"t-caption\">Teams</span><p class=\"t-label\">3 adopted with zero added a11y effort</p></div><div><span class=\"t-caption\">Engineering</span><p class=\"t-label\">Fewer regressions, faster delivery</p></div></div>\n    </div>\n    <div class=\"slide\">\n      <div class=\"s-l\"><span class=\"t-caption\">05 · Outcome</span><p class=\"big\">Accessibility became <em>the default.</em></p><p class=\"t-small\">0 axe-core violations, verified manually with NVDA and VoiceOver.</p></div>\n      <div class=\"s-r s-deltas\"><div><span class=\"t-caption\">Contrast pass rate</span><div class=\"delta\"><s>37%</s><span class=\"arr\">→</span><b>100%</b></div></div><p class=\"t-caption\">24 components · 3 teams · 11k+ volunteers</p></div>\n    </div>\n    <div class=\"sum-nav\"><span class=\"t-caption\" id=\"sumCount\">1 / 5</span><button class=\"icon-btn glass\" id=\"sumPrev\" aria-label=\"Previous slide\">←</button><button class=\"icon-btn glass\" id=\"sumNext\" aria-label=\"Next slide\">→</button></div>\n  </div>\n</div>";
export const js = "\n(function(){\n  var root=document.documentElement;\n  var reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;\n  document.getElementById('themeBtn').addEventListener('click',function(){var cur=root.getAttribute('data-theme')||'dark';root.setAttribute('data-theme',cur==='dark'?'light':'dark')});\n  var links=[].slice.call(document.querySelectorAll('#toc a'));\n  if('IntersectionObserver' in window){\n    var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){links.forEach(function(a){a.classList.toggle('on',a.getAttribute('href')==='#'+e.target.id)})}})},{rootMargin:'-40% 0px -55% 0px'});\n    links.forEach(function(a){var s=document.querySelector(a.getAttribute('href'));s&&io.observe(s)});\n  }\n  if(!reduce&&'IntersectionObserver' in window){\n    var vh=innerHeight;\n    var ro=new IntersectionObserver(function(es){es.forEach(function(e){if(!e.isIntersecting)return;var el=e.target;ro.unobserve(el);requestAnimationFrame(function(){el.classList.remove('pre-r')})})},{threshold:.2});\n    [].forEach.call(document.querySelectorAll('.reveal'),function(el){if(el.getBoundingClientRect().top>vh*0.9){el.classList.add('pre-r');ro.observe(el)}});\n  }\n  /* hero video: site file on jihokim.me/localhost; poster elsewhere and with reduced motion */\n  (function(){\n    var v=document.getElementById('heroVideo'); if(!v) return;\n    var host=location.hostname, onSite=/(^|\\.)jihokim\\.me$/.test(host)||host==='localhost'||host==='127.0.0.1';\n    if(!onSite||reduce){v.removeAttribute('autoplay');return;}\n    v.querySelector('source').src=v.dataset.site; v.load(); var p=v.play&&v.play(); p&&p.catch&&p.catch(function(){});\n  })();\n  /* heatmap findings */\n  var mks=[].slice.call(document.querySelectorAll('.mk')), finds=[].slice.call(document.querySelectorAll('.find'));\n  function pick(i){mks.forEach(function(m){m.classList.toggle('on',m.dataset.f==i)});finds.forEach(function(f){f.classList.toggle('on',f.dataset.f==i)})}\n  mks.forEach(function(m){m.addEventListener('click',function(){pick(m.dataset.f)})});\n  finds.forEach(function(f){f.addEventListener('click',function(){pick(f.dataset.f)})});\n  pick('0');\n  /* legacy vs system */\n  var V={legacy:{C:37,K:42,S:28,F:51,cls:'bad',sum:'Fails WCAG 2.2 AA · 4 button styles · low-contrast text'},\n         system:{C:100,K:100,S:100,F:100,cls:'good',sum:'0 axe-core violations · passes WCAG 2.2 AA'}};\n  var seg=[].slice.call(document.querySelectorAll('.seg button')), prev=document.getElementById('uiPrev'), sys=document.getElementById('sysDemo');\n  function set(v){\n    var d=V[v]; seg.forEach(function(b){b.setAttribute('aria-checked',b.dataset.v===v?'true':'false')});\n    prev.classList.toggle('legacy',v==='legacy'); prev.classList.toggle('system',v==='system'); sys.classList.toggle('on',v==='system');\n    [['C','aC','vC'],['K','aK','vK'],['S','aS','vS'],['F','aF','vF']].forEach(function(r){document.getElementById(r[1]).style.setProperty('--w',d[r[0]]+'%');document.getElementById(r[2]).textContent=d[r[0]]+'%'});\n    [].forEach.call(prev.querySelectorAll('[data-l]'),function(n){n.textContent=v==='system'?n.dataset.s:n.dataset.l});\n    var s=document.getElementById('aSum'); s.className='sa-sum '+d.cls; s.textContent=d.sum;\n  }\n  seg.forEach(function(b){b.addEventListener('click',function(){set(b.dataset.v)})});\n  set('legacy');\n  /* summary mode */\n  var sum=document.getElementById('sum'), slides=[].slice.call(sum.querySelectorAll('.slide')), dots=[].slice.call(sum.querySelectorAll('#sumDots i')), cur=0, lastFocus=null;\n  function go(i){cur=(i+slides.length)%slides.length;slides.forEach(function(s,j){s.classList.toggle('on',j===cur)});dots.forEach(function(d,j){d.classList.toggle('on',j<=cur)});document.getElementById('sumCount').textContent=(cur+1)+' / '+slides.length}\n  function open(){lastFocus=document.activeElement;sum.hidden=false;go(0);document.getElementById('sumNext').focus();document.body.style.overflow='hidden'}\n  function close(){sum.hidden=true;document.body.style.overflow='';lastFocus&&lastFocus.focus()}\n  [].forEach.call(document.querySelectorAll('[data-open-summary]'),function(b){b.addEventListener('click',open)});\n  document.getElementById('sumClose').addEventListener('click',close);\n  document.getElementById('sumNext').addEventListener('click',function(){go(cur+1)});\n  document.getElementById('sumPrev').addEventListener('click',function(){go(cur-1)});\n  sum.addEventListener('click',function(e){if(e.target===sum)close()});\n  document.addEventListener('keydown',function(e){if(sum.hidden)return;if(e.key==='Escape')close();if(e.key==='ArrowRight')go(cur+1);if(e.key==='ArrowLeft')go(cur-1)});\n})();\n";
